package net.civeira.phylax.features.oauth.client.domain.exception;

/**
 * Domain exception for Dynamic Client Registration errors (RFC 7591 §3.2.2, RFC 7592 §2).
 *
 * <p>
 * Each error carries the HTTP status the driver must answer with: 400 for invalid metadata, 401 for
 * a missing or unusable initial or registration access token, 403 when the tenant does not accept
 * registrations.
 */
public class DynamicClientException extends RuntimeException {
  private static final long serialVersionUID = -3859531151560728159L;

  private final String errorCode;
  private final int status;

  private DynamicClientException(String errorCode, int status, String message) {
    super(message);
    this.errorCode = errorCode;
    this.status = status;
  }

  public String getErrorCode() {
    return errorCode;
  }

  /**
   * HTTP status of the error.
   *
   * @return status code
   */
  public int getStatus() {
    return status;
  }

  public static DynamicClientException registrationNotAllowed() {
    return new DynamicClientException("access_denied", 403,
        "Dynamic client registration is disabled for this tenant");
  }

  /**
   * Missing, unknown, expired, revoked or exhausted initial access token (RFC 6750 §3.1). Kept
   * apart from the registration access token error so a client knows which credential failed.
   */
  public static DynamicClientException tokenRequired() {
    return new DynamicClientException("invalid_token", 401,
        "A valid initial access token is required to register clients");
  }

  /**
   * Missing or wrong registration access token, or a client of another tenant (RFC 7592 §2).
   */
  public static DynamicClientException invalidRegistrationToken() {
    return new DynamicClientException("invalid_token", 401,
        "Invalid registration access token for this client");
  }

  public static DynamicClientException invalidRedirectUri(String uri) {
    return new DynamicClientException("invalid_redirect_uri", 400,
        "Redirect URI is not allowed: " + uri);
  }

  public static DynamicClientException invalidClientMetadata(String reason) {
    return new DynamicClientException("invalid_client_metadata", 400, reason);
  }
}
